verus! {
    /// Linear search for `target` in the vector `nums`.
    /// Returns the index of the first occurrence of `target` as an `i32`,
    /// or returns -1 if `target` is not found.
    fn linear_search(nums: Vec<i32>, target: i32) -> (ret: i32)
        requires
            // We require the length to fit in an i32.
            (nums.len() as u64) < 0x8000_0000,  
        ensures
            // If we return a non‐negative index, it is in range,
            // the element there equals `target`, and no earlier element equals `target`.
            (ret >= 0 ==>
                {
                    let idx: usize = ret as usize;
                    idx < nums.len() &&
                    nums[idx] == target &&
                    #[verifier::forall](|j: usize| j < idx ==> nums[j] != target)
                }
            ),
        ensures
            // If we return -1 (a negative value), then `target` does not occur anywhere.
            (ret < 0 ==>
                #[verifier::forall](|j: usize| j < nums.len() ==> nums[j] != target)
            ),
        ensures
            // In all cases, the return value is strictly less than the length.
            ret < (nums.len() as i32),
    {
        let len = nums.len();
        let mut idx: usize = 0;

        // Scan until we either find `target` or exhaust the array.
        while idx < len && nums[idx] != target
            invariant
                // We never step past the end.
                idx <= len,
                // All positions before `idx` are known not to contain `target`.
                #[verifier::forall](|j: usize| j < idx ==> nums[j] != target)
            decreases
                len - idx,
        {
            idx += 1;
        }

        if idx < len {
            // Found the target at position `idx`.
            ret = idx as i32;
        } else {
            // Not found at any position.
            ret = -1;
        }
    }
}

